// FATURAÇÃO (documento fiscal — distinto do recibo simples)
// ---------------------------------------------------------------------
function Faturacao({ membros, planos }) {
  const [membroId, setMembroId] = useState("");
  const [gerada, setGerada] = useState(null);
  const [historico, setHistorico] = useState([]);

  const gerar = () => {
    const membro = membros.find((m) => m.id === Number(membroId));
    if (!membro) return;
    const plano = planos.find((p) => p.nome === membro.plano);
    const numero = "FAT-2026-" + String(historico.length + 1).padStart(6, "0");
    const fatura = {
      numero,
      membro,
      valor: plano?.preco || 15000,
      data: new Date().toLocaleDateString("pt-PT"),
    };
    setGerada(fatura);
    setHistorico([fatura, ...historico]);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
      <Card title="Gerar fatura">
        <div className="space-y-3">
          <div>
            <label className="text-xs font-medium text-slate-500 dark:text-slate-400">Membro</label>
            <select value={membroId} onChange={(e) => setMembroId(e.target.value)}
              className="w-full mt-1 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-[#BFE4E1]">
              <option value="">Selecionar membro...</option>
              {membros.map((m) => <option key={m.id} value={m.id}>{m.nome} — {m.numero}</option>)}
            </select>
          </div>
          <button onClick={gerar} className="w-full bg-[#3F8F87] hover:bg-[#347871] text-white font-semibold py-2.5 rounded-lg text-sm">
            Gerar fatura
          </button>
        </div>

        {historico.length > 0 && (
          <div className="mt-5">
            <p className="text-xs font-medium text-slate-500 dark:text-slate-400 mb-2">Faturas emitidas</p>
            <div className="divide-y divide-slate-50 dark:divide-slate-700">
              {historico.map((f) => (
                <div key={f.numero} className="flex justify-between py-2 text-sm">
                  <span className="text-slate-600 dark:text-slate-300">{f.numero} · {f.membro.nome}</span>
                  <span className="font-medium text-slate-900 dark:text-slate-100">{kz(f.valor)}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </Card>

      <Card title="Pré-visualização">
        {!gerada ? (
          <p className="text-sm text-slate-400 dark:text-slate-500">Gera uma fatura para veres a pré-visualização.</p>
        ) : (
          <div className="bg-white dark:bg-slate-100 rounded-xl ring-1 ring-slate-200 p-5 text-slate-800">
            <div className="flex items-center justify-between mb-4">
              <img src={LOGO_BASE64} alt="Catumbela Gym" className="h-10" />
              <div className="text-right">
                <p className="font-bold text-sm">FATURA</p>
                <p className="text-xs text-slate-500">Nº {gerada.numero}</p>
              </div>
            </div>
            <div className="text-sm space-y-1 mb-4">
              <p><span className="text-slate-500">Cliente:</span> {gerada.membro.nome}</p>
              <p><span className="text-slate-500">Nº de membro:</span> {gerada.membro.numero}</p>
              <p><span className="text-slate-500">Data:</span> {gerada.data}</p>
            </div>
            <div className="border-t border-b border-slate-200 py-3 flex justify-between text-sm">
              <span>Mensalidade — Plano {gerada.membro.plano}</span>
              <span className="font-medium">{kz(gerada.valor)}</span>
            </div>
            <div className="flex justify-between text-sm font-bold mt-3">
              <span>Total</span>
              <span className="text-[#3F8F87]">{kz(gerada.valor)}</span>
            </div>
            <div className="flex gap-2 mt-5">
              <button className="flex-1 border border-slate-200 rounded-lg py-2 text-sm font-semibold hover:bg-slate-50">
                Baixar PDF
              </button>
              <button className="flex-1 border border-slate-200 rounded-lg py-2 text-sm font-semibold hover:bg-slate-50">
                Imprimir
              </button>
              <a
                href={linkWhatsApp(gerada.membro.telefone, `Segue a sua fatura ${gerada.numero} — ${kz(gerada.valor)}. Catumbela Gym.`)}
                target="_blank" rel="noreferrer"
                className="flex-1 bg-[#3F8F87] hover:bg-[#347871] text-white rounded-lg py-2 text-sm font-semibold text-center"
              >
                Enviar
              </a>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

// ---------------------------------------------------------------------
// NOTIFICAÇÕES AUTOMÁTICAS
// ---------------------------------------------------------------------
function calcularNotificacoes(membros) {
  const hoje = new Date("2026-08-20"); // data de referência do sistema
  return membros
    .map((m) => {
      const venc = new Date(m.vencimento);
      const dias = Math.round((venc - hoje) / (1000 * 60 * 60 * 24));
      let tipo = null;
      let mensagem = "";
      if (dias === 5) {
        tipo = "aviso";
        mensagem = `Olá ${m.nome.split(" ")[0]}, a sua mensalidade da Catumbela Gym vence em 5 dias (${m.vencimento}).`;
      } else if (dias === 0) {
        tipo = "hoje";
        mensagem = `Olá ${m.nome.split(" ")[0]}, a sua mensalidade vence hoje. Regularize para continuar ativo.`;
      } else if (dias < 0) {
        tipo = "vencido";
        mensagem = `Olá ${m.nome.split(" ")[0]}, a sua mensalidade está vencida desde ${m.vencimento}. Regularize o pagamento para continuar a utilizar o ginásio.`;
      }
      return tipo ? { membro: m, tipo, mensagem, dias } : null;
    })
    .filter(Boolean);
}

const ESTILO_NOTIFICACAO = {
  aviso: { cor: "text-amber-600 bg-amber-50 dark:bg-amber-900/20", rotulo: "Vence em breve" },
  hoje: { cor: "text-[#3F8F87] bg-[#EAF5F4] dark:bg-slate-700", rotulo: "Vence hoje" },
  vencido: { cor: "text-red-600 bg-red-50 dark:bg-red-900/20", rotulo: "Vencido" },
};

