// ---------------------------------------------------------------------
// TURNO DE CAIXA (conta da recepcionista)
// ---------------------------------------------------------------------
function TurnoCaixa({ pagamentosFeitos }) {
  const [aberto, setAberto] = useState(false);
  const [fechado, setFechado] = useState(false);

  const totais = useMemo(() => {
    const t = { dinheiro: 0, tpa: 0, express: 0, referencia: 0 };
    pagamentosFeitos.forEach((p) => { t[p.metodo] = (t[p.metodo] || 0) + p.valor; });
    return t;
  }, [pagamentosFeitos]);
  const totalGeral = Object.values(totais).reduce((a, b) => a + b, 0);

  if (!aberto) {
    return (
      <Card title="Turno de caixa">
        <p className="text-sm text-slate-500 dark:text-slate-400 dark:text-slate-500 mb-4">Ainda não abriste o teu turno hoje.</p>
        <button onClick={() => setAberto(true)} className="bg-[#3F8F87] hover:bg-[#347871] text-white font-semibold px-5 py-2.5 rounded-lg text-sm">
          Abrir turno
        </button>
      </Card>
    );
  }

  return (
    <Card title={fechado ? "Turno fechado — resumo" : "Turno aberto"}>
      <div className="space-y-2 mb-4">
        {[
          { label: "Dinheiro", value: totais.dinheiro },
          { label: "TPA", value: totais.tpa },
          { label: "MULTICAIXA Express", value: totais.express },
          { label: "Referência", value: totais.referencia },
        ].map((r) => (
          <div key={r.label} className="flex justify-between text-sm py-1.5 border-b border-slate-50 last:border-0">
            <span className="text-slate-600 dark:text-slate-300">{r.label}</span>
            <span className="font-medium text-slate-900 dark:text-slate-100">{kz(r.value)}</span>
          </div>
        ))}
        <div className="flex justify-between text-sm pt-2 font-bold">
          <span>Total</span>
          <span className="text-[#3F8F87]">{kz(totalGeral)}</span>
        </div>
      </div>
      {!fechado ? (
        <button onClick={() => setFechado(true)} className="bg-slate-900 hover:bg-slate-800 text-white font-semibold px-5 py-2.5 rounded-lg text-sm">
          Fechar turno
        </button>
      ) : (
        <p className="text-sm text-emerald-600 font-medium">Turno fechado — conferido pelo administrador.</p>
      )}
    </Card>
  );
}

